        koreys_subject = Subject.objects.filter(name='Koreys tili').first()
        if koreys_subject:
            koreys_target = Level.objects.filter(subject=koreys_subject, name='Koreys tili 1').first()
            for old_name in ['Koreys 1', 'Koreys tili', 'Koreys']:
                old_level = Level.objects.filter(subject=koreys_subject, name=old_name).first()
                if old_level and koreys_target and old_level.id != koreys_target.id:
                    Student.objects.filter(subject=koreys_subject, level=old_level).update(level=koreys_target, selected_version=None)
                    Question.objects.filter(subject=koreys_subject, level=old_level).delete()
