        def reset_single_level(subject_name, level_name, questions, duration_minutes=30, old_level_names=None):
            old_level_names = old_level_names or []
            subject, _ = Subject.objects.get_or_create(name=subject_name)

            target_level = Level.objects.filter(subject=subject, name=level_name).first()
            if not target_level:
                for old_name in old_level_names:
                    old_level = Level.objects.filter(subject=subject, name=old_name).first()
                    if old_level:
                        old_level.name = level_name
                        old_level.duration_minutes = duration_minutes
                        old_level.save(update_fields=['name', 'duration_minutes'])
                        target_level = old_level
                        break
            if not target_level:
                target_level, _ = Level.objects.get_or_create(
                    subject=subject,
                    name=level_name,
                    defaults={'duration_minutes': duration_minutes},
                )
            if target_level.duration_minutes != duration_minutes:
                target_level.duration_minutes = duration_minutes
                target_level.save(update_fields=['duration_minutes'])

            for old_name in old_level_names:
                for old_level in Level.objects.filter(subject=subject, name=old_name).exclude(id=target_level.id):
                    # Agar eski darajaga o'quvchi biriktirilgan bo'lsa, ularni yangi darajaga ko'chiramiz.
                    Student.objects.filter(subject=subject, level=old_level).update(level=target_level)
                    Question.objects.filter(subject=subject, level=old_level).delete()
                    old_level.delete()

            Question.objects.filter(subject=subject, level=target_level).delete()
            for text, a, b, c, d, correct in questions:
                Question.objects.create(
                    subject=subject,
                    level=target_level,
                    version=1,
                    text=text,
                    option_a=a,
                    option_b=b,
                    option_c=c,
                    option_d=d,
                    correct_answer=correct,
                )

